using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evaluation;

[TestClass]
public class ChatEvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        await _app.DisposeAsync();
    }

    [TestMethod]
    public async Task Greeting_ReturnsRelevantResponse()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var response = await chatClient.GetResponseAsync("Hello, who are you and how can you help me?");

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
        };

        var chatHistory = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, who are you and how can you help me?"),
            new(ChatRole.Assistant, response.Text),
        };

        foreach (var evaluator in evaluators)
        {
            var result = await evaluator.EvaluateAsync(chatHistory);
            foreach (var metric in result)
            {
                Assert.IsFalse(
                    metric.Interpretation?.Rating == EvaluationRating.Inconclusive,
                    $"Evaluator '{evaluator.GetType().Name}' returned inconclusive for greeting scenario.");
            }
        }
    }

    [TestMethod]
    public async Task FactualQuestion_ReturnsAccurateAnswer()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var response = await chatClient.GetResponseAsync("What is the capital of France?");

        Assert.IsNotNull(response.Text);
        Assert.IsTrue(
            response.Text.Contains("Paris", StringComparison.OrdinalIgnoreCase),
            "Expected the response to mention Paris.");

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new GroundednessEvaluator(),
        };

        var chatHistory = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?"),
            new(ChatRole.Assistant, response.Text),
        };

        foreach (var evaluator in evaluators)
        {
            var result = await evaluator.EvaluateAsync(chatHistory);
            foreach (var metric in result)
            {
                Assert.IsFalse(
                    metric.Interpretation?.Rating == EvaluationRating.Inconclusive,
                    $"Evaluator '{evaluator.GetType().Name}' returned inconclusive for factual-question scenario.");
            }
        }
    }

    [TestMethod]
    public async Task MultiTurnContext_MaintainsConversationState()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var history = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice."),
        };

        var firstResponse = await chatClient.GetResponseAsync(history);
        history.Add(new ChatMessage(ChatRole.Assistant, firstResponse.Text));
        history.Add(new ChatMessage(ChatRole.User, "What is my name?"));

        var secondResponse = await chatClient.GetResponseAsync(history);
        history.Add(new ChatMessage(ChatRole.Assistant, secondResponse.Text));

        Assert.IsTrue(
            secondResponse.Text.Contains("Alice", StringComparison.OrdinalIgnoreCase),
            "Expected the model to recall the name 'Alice' from the prior turn.");

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
        };

        foreach (var evaluator in evaluators)
        {
            var result = await evaluator.EvaluateAsync(history);
            foreach (var metric in result)
            {
                Assert.IsFalse(
                    metric.Interpretation?.Rating == EvaluationRating.Inconclusive,
                    $"Evaluator '{evaluator.GetType().Name}' returned inconclusive for multi-turn scenario.");
            }
        }
    }
}

